import xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
tree=ET.parse('xl/worksheets/sheet1.xml')
root=tree.getroot()
sd=root.find('m:sheetData',ns)
rows={}
for row in sd.findall('m:row',ns):
    r=int(row.get('r'))
    rows[r]={}
    for c in row.findall('m:c',ns):
        ref=c.get('r')
        if ref.startswith(('A','B')):
            v=c.find('m:v',ns)
            rows[r][ref]=v.text if v is not None else None
for r in range(1,67):
    print(r, rows.get(r,{}))
EOF

